export function assertSourceCatalogShape(): void {
  const ids = new Set<string>();
  for (const source of SOURCE_CATALOG) {
    if (ids.has(source.id)) {
      throw new Error(`Duplicate source id: ${source.id}`);
    }
    ids.add(source.id);
  }
  const web = SOURCE_CATALOG.filter((source) => source.group === 'web').length;
  const telegram = SOURCE_CATALOG.filter((source) => source.group === 'telegram').length;
  const vk = SOURCE_CATALOG.filter((source) => source.group === 'vk').length;
  if (SOURCE_CATALOG.length !== 103 || web !== 53 || telegram !== 35 || vk !== 15) {
    throw new Error(`Invalid source catalog size: total=${SOURCE_CATALOG.length}, web=${web}, telegram=${telegram}, vk=${vk}`);
  }
}

assertSourceCatalogShape();
